-- UnitNamesData.lua —— 本服「生物名 → 生物 id」三语表（**生成物，绝不手改**）
--
-- 出处：unrealUI 0.10.2（MIT）的 Database\unit_names.lua / unit_names_zhCN.lua / unit_names_ruRU.lua
--       （本服 VMaNGOS 名字快照）；表体逐字节保留，只改挂点与 locale 闸门。
-- 为什么要名字表：本客户端**没有** UnitGUID / 生物 id 读口（unrealUI core/unitvitals.lua 顶部在案）
--       ⇒ 查表的唯一键是 `UnitName(unit)` + `UnitLevel(unit)`，所以名字必须与客户端**逐字相符**。
-- ★★与 unrealUI 的差别（本项目口径）：它把三份表做成**互斥备选**（各文件首行按 GetLocale 早退）⇒
--   zhCN 客户端只拿 10,239 个 id；这里改成 **enUS 恒载入（回退表）+ 客户端 locale 那一份**：
--   本服 zhCN 数据里有一批怪**没有中文名**（客户端直接显示英文名，128 个 id）⇒ 只带 zhCN 表就查不到。
--   已复算：并集覆盖 10,367 / 10,369 个 id，且 **(名字,等级) → 最大生命值 冲突仍为 0**。
-- ★生成方式：node tmp/gen_unitdata.js；出处与许可 = doc\目标生命值数据-出处与许可.md

-- enUS：恒载入（既是英文客户端的主表，也是其它语言客户端的**回退表**）
